export function getChallengeTopics() {
  return [
    { id:'f1_podiums',    label:'F1 Podiums',           emoji:'🥇', color:'#ef4444', description:'Guess the 1st, 2nd and 3rd in order' },
    { id:'f1_points',     label:'F1 Points Scorers',    emoji:'📊', color:'#f97316', description:'Who finished where in famous races?' },
    { id:'pl_seasons',    label:'Premier League',       emoji:'🏴󠁧󠁢󠁥󠁮󠁧󠁿', color:'#4f6ef7', description:'PL winners, top scorers, cup winners' },
    { id:'fa_cup',        label:'FA Cup',               emoji:'🏆', color:'#7c3aed', description:'Famous FA Cup moments and winners' },
    { id:'wc_podiums',    label:'World Cup Podiums',    emoji:'🌍', color:'#22c55e', description:'Top 3 finishers at each World Cup' },
    { id:'wc_questions',  label:'World Cup Trivia',     emoji:'⚽', color:'#0ea5e9', description:'Goals, records, golden boots' },
    { id:'guess_player',  label:'Guess the Player',     emoji:'🕵️', color:'#a78bfa', description:'Nationality + career clues — who am I?' },
    { id:'guess_team',    label:'Guess the Team',       emoji:'🎽', color:'#f472b6', description:'Squad nationalities and trivia' },
  ]
}

export function getChallenge(topicId) {
  const bank = CHALLENGES[topicId] || []
  if (!bank.length) return null
  return bank[Math.floor(Math.random() * bank.length)]
}

export function getChallengeBank(topicId) {
  return CHALLENGES[topicId] || []
}

// Questions marked dual:true are also available in Quickfire/Endless mode
export function getDualModeQuestions() {
  const result = {}
  Object.entries(CHALLENGES).forEach(([topicId, questions]) => {
    const dual = questions.filter(q => q.dual)
    if (dual.length > 0) {
      result[topicId] = dual.map(q => ({
        q: q.q, a: q.a, h: q.h||'', f: q.f||'', dual:true, _challengeTopic: topicId
      }))
    }
  })
  return result
}
